INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', '360Player is a sports club management platform that brings all working tools into one place, so clubs don''t switch between services or lose time on repetitive admin. Clubs handle registrations and memberships, take payments with competitive fees, communicate with players, coaches and parents, organize training and follow player development. The solution adapts to each club''s structure and goals and suits organizations of every size, from grassroots clubs to elite academies. The 360Player team migrates members and teams from the previous system and guides setup, so most clubs are up and running in days. Pricing depends on membership size and modules used, so it is quoted individually after a conversation with sales.', 'manual' FROM DUAL WHERE @new = 1;
