INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'ABC Trainerize helps fitness professionals deliver customized programs, track client progress and grow their business. It is used by independent coaches, nutrition, lifestyle and wellness coaches, studios, gyms, fitness clubs and corporate wellness programs. It supports online, in-person, hybrid and group training as well as nutrition coaching. For coaching there is an AI-assisted workout builder and modules for nutrition, habits and motivation. For engagement there is messaging, community and video coaching. For running the business there is scheduling, payments, client and team management, and integrations. For growth there are FitMetrics analytics, marketing tools and custom branded apps. An academy offers business courses and masterclasses.', 'manual' FROM DUAL WHERE @new = 1;
