SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'coachmeplus.com' OR LOWER(`name`) = LOWER('CoachMePlus'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'CoachMePlus', NULL, 'https://coachmeplus.com', NULL, NULL, 'Система керування спортсменами для тренерів: конструктор тренувань, панелі даних, опитувальники самопочуття, тестування й розклад, а для спортсменів — тренування, харчування, гідратація, інтеграція з носимими пристроями й повідомлення.', 'An athlete management system for coaches: a workout builder, dashboards, wellness questionnaires, testing and scheduling, while athletes get workouts, nutrition, hydration, wearable integrations and messaging.', 'CoachMePlus — програма для розвитку фізичних можливостей людини, яка допомагає тренерам і спортсменам працювати разом і правильно розуміти дані. Тренер отримує інструменти для обґрунтованих рішень: набір тренерських інструментів, конструктор тренувань, панелі даних, опитувальники самопочуття, тестування й розклад. Спортсмен — тренування, харчування, контроль гідратації, самопочуття, інтеграцію з носимими пристроями й повідомлення. Усі дані про результати спортсменів зберігаються в одному центрі, тож тренер легко тримає руку на пульсі без зайвого навантаження. Систему керування спортсменами можна повністю налаштувати під себе, а складні дані — від тренувань до самопочуття — стають простішими для аналізу в реальному часі й на тривалому відрізку. Є безкоштовна спроба й демонстрація.', 'CoachMePlus is human performance software that helps coaches and athletes work together and read the data correctly. Coaches get tools for informed decisions: a coaching toolkit, workout builder, dashboards, wellness questionnaires, testing and scheduling. Athletes get workouts, nutrition, hydration, wellness tracking, wearable integrations and messaging. All athlete performance data lives in one central place, so coaches stay up to date without extra workload. The athlete management system is fully customizable, and complex data, from workouts to wellness, becomes easier to analyze in real time and over the long term. A free trial and demos are available.', 'Конструктор тренувань і програм
Панелі даних про спортсменів
Опитувальники самопочуття
Тестування й розклад
Харчування й гідратація
Інтеграція з носимими пристроями
Повідомлення між тренером і спортсменом', 'Workout and program builder
Athlete data dashboards
Wellness questionnaires
Testing and scheduling
Nutrition and hydration
Wearable integrations
Coach and athlete messaging', 'Тренери з фізпідготовки, команди й організації, які працюють зі спортсменами.', 'Strength coaches, teams and organizations working with athletes.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
