SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'everfit.io' OR LOWER(`name`) = LOWER('Everfit'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Everfit', NULL, 'https://everfit.io', NULL, NULL, 'Платформа для фітнес-тренерів, нутриціологів, спортивних тренерів і залів: складання тренувань із підтримкою AI, плани харчування, звички, спортивні вправи й аналітика, індивідуальна й групова робота з клієнтами в одному місці.', 'A platform for fitness coaches, nutrition coaches, sport coaches and gyms: AI-assisted workout programming, meal plans, habits, sport drills and analytics, with one-to-one and group coaching in one place.', 'Everfit — універсальна платформа для фітнес- і велнес-коучингу, яка допомагає тренерам, залам, студіям, нутриціологам і спортивним тренерам масштабувати свою роботу. Тренування можна планувати з підтримкою штучного інтелекту, а для харчування є гнучкі плани з контролем виконання. Модуль звичок допомагає вибудовувати корисні рутини, а спортивний коучинг додає вправи на навички й аналітику результатів. Платформа підтримує й індивідуальну роботу з персональними планами, перевірками й прямим зв''язком, і груповий формат із тренуваннями на вимогу, спільнотою й онлайн-челенджами. Є бібліотека з понад 1000 вправ або власні вправи з відео, відстеження показників і фото прогресу, завдання з нагадуваннями, повідомлення, окремі застосунки для клієнта й тренера. Безкоштовний план дозволяє вести до 5 клієнтів.', 'Everfit is an all-in-one fitness and wellness coaching platform that helps trainers, gyms, studios, nutrition coaches and sport coaches scale their work. Workouts can be planned with AI assistance, and flexible meal plans provide guidance and accountability. Habit coaching builds routines that last, while sport coaching adds skill-based drills and performance analytics. The platform supports both one-to-one work with personalized plans, check-ins and direct communication, and one-to-many formats with on-demand content, community forums and online challenges. There is a library of more than 1,000 exercises or your own branded videos, metrics and progress photos, tasks with reminders, messaging, and separate client and coach apps. The free plan covers up to 5 clients.', 'Планування тренувань із підтримкою AI
Плани харчування й коучинг звичок
Спортивні вправи й аналітика результатів
Індивідуальна й групова робота з клієнтами
Понад 1000 вправ або власні відео
Показники й фото прогресу
Застосунки для клієнтів і тренерів', 'AI-assisted workout programming
Meal plans and habit coaching
Sport drills and performance analytics
One-to-one and group coaching
1,000+ exercises or custom videos
Metrics and progress photos
Client and coach apps', 'Персональні й онлайн-тренери, нутриціологи, спортивні тренери, зали й студії.', 'Personal and online trainers, nutrition coaches, sport coaches, gyms and studios.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
