-- GameChanger — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gc.com' OR LOWER(`name`) = LOWER('GameChanger'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'GameChanger', NULL, 'https://gc.com', NULL, NULL, 'Застосунок для дитячого спорту: безкоштовне керування командою й ведення рахунку для тренерів, склади й розклад, повідомлення, статистика гри, а для родин — трансляції матчів у Full HD, повтори й хайлайти.', 'A youth sports app: free team management and scorekeeping for coaches, lineups and scheduling, messaging, game stats, and for families, Full HD livestreams, replays and highlights.', 'GameChanger допомагає тренерам, родинам і вболівальникам дитячого спорту бути на зв''язку з командою. Для тренерів застосунок завжди безкоштовний і збирає всі інструменти в одному місці: керування командою, ведення рахунку в застосунку, склади, розклад, повідомлення команді та статистика гри, щоб бути організованим і підготовленим увесь сезон. Кожну гру можна транслювати наживо у Full HD, дивитися з будь-якого місця, отримувати сповіщення й синхронізувати календар. Після гри родини переглядають повні записи й огляди, діляться хайлайтами й важливими моментами та створюють профіль кар''єри юного спортсмена. Платні можливості для вболівальників доступні за підпискою. Застосунок працює на телефоні й комп''ютері.', 'GameChanger keeps coaches, families and fans of youth sports connected with their team. For coaches the app is always free and puts every tool in one place: team management, in-app scoring, lineups, scheduling, team messaging and game insights to stay organized and prepared all season. Every game can be livestreamed in Full HD, watched from anywhere, with live alerts and calendar sync. After the game, families watch full games and recaps, share highlights and milestones, and build a career profile for their athlete. Paid features for fans are available by subscription. The app runs on phones and computers.', 'Безкоштовне керування командою для тренерів
Ведення рахунку й статистика гри
