-- Hudl — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hudl.com' OR LOWER(`name`) = LOWER('Hudl'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hudl', NULL, 'https://hudl.com', NULL, NULL, 'Платформа спортивних технологій для тренерів і команд: AI-камери автоматично знімають і транслюють матчі, відео й дані допомагають аналізувати гру, готуватися до суперників, стежити за спортсменами, шукати таланти й керувати клубом.', 'A sports technology platform for coaches and teams: AI cameras record and livestream games automatically, while video and data help analyze play, prepare for opponents, track athletes, scout talent and run the club.', 'Hudl допомагає спортсменам, тренерам, командам і організаціям на будь-якому рівні отримувати більше від кожного матчу завдяки відео, даним і штучному інтелекту. AI-камери Focus у високій якості автоматично знімають, транслюють і поширюють гру без оператора — ці записи використовують для розвитку гравців, трансляцій і хайлайтів. Для командної роботи є дані й аналітика з підтримкою AI, які допомагають тренерам будувати сильніші команди й готуватися до суперників. Індивідуальний трекінг допомагає оптимізувати результати й відновлення кожного спортсмена. Окремі інструменти пов''язують спортсменів зі скаутами й рекрутерами. Для вболівальників доступні трансляції, хайлайти, профілі й квитки, а для організацій — розклади, логістика й платежі. До екосистеми Hudl входять Wyscout, StatsBomb, Volleymetrics, Instat та інші продукти.', 'Hudl helps athletes, coaches, teams and organizations at every level get more out of every game with video, data and AI. Focus AI cameras record, livestream and share games in HD automatically, without a camera operator, and the footage fuels player development, livestreams and highlights. For team performance there is AI-assisted data and insights that help coaches build better teams and prepare for opponents. Individual tracking helps optimize each athlete''s performance and recovery. Dedicated tools connect athletes with scouts and recruiters. Fans get livestreams, highlights, profiles and tickets, and organizations get scheduling, logistics and payments. The Hudl ecosystem includes Wyscout, StatsBomb, Volleymetrics, Instat and other products.', 'AI-камери для автоматичної зйомки й трансляцій
Відеоаналіз ігор і підготовка до суперників
Дані й аналітика команди з підтримкою AI
Індивідуальний трекінг спортсменів
Скаутинг і рекрутинг
Трансляції й хайлайти для вболівальників
Розклади, логістика й платежі для клубів', 'AI cameras for automatic recording and livestreams
Game video analysis and opponent prep
AI-assisted team data and insights
Individual athlete tracking
Scouting and recruiting
Livestreams and highlights for fans
Scheduling, logistics and payments for clubs', 'Тренери, команди, клуби й спортивні організації будь-якого рівня — від шкільного спорту до професійних ліг.', 'Coaches, teams, clubs and sports organizations at every level, from school sports to pro leagues.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
