SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'mypthub.net' OR LOWER(`name`) = LOWER('My PT Hub'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'My PT Hub', NULL, 'https://mypthub.net', NULL, NULL, 'Програма й застосунок для персональних тренерів: конструктор тренувань із підтримкою AI, плани харчування, бронювання занять, облік результатів клієнтів, прийом оплат і брендований застосунок. Без обмежень на кількість клієнтів у старшому плані.', 'Software and an app for personal trainers: an AI-assisted workout builder, nutrition plans, session booking, client results tracking, payments and a branded app, with no client cap on the higher plan.', 'My PT Hub — універсальна програма для персональних тренерів і фітнес-коучів, створена тренерами для тренерів. В одному місці можна вести клієнтів, видавати тренування й плани харчування, приймати оплати й розвивати бізнес. Конструктор тренувань із підтримкою AI допомагає швидко створювати, призначати й відстежувати програми. Є коучинг харчування з індивідуальними планами, бронювання індивідуальних і групових занять та подій, облік результатів для мотивації клієнтів, звички, показники й фото прогресу, чат. Зручний клієнтський застосунок допомагає утримувати й залучати клієнтів, а інструменти брендування дозволяють отримати застосунок під власною назвою. Додатково доступні AI-перевірки клієнтів і інтеграція з Zapier. Є 30-денний безкоштовний період без картки.', 'My PT Hub is all-in-one software for personal trainers and fitness coaches, built by coaches for coaches. In one place you can manage clients, deliver workouts and nutrition plans, take payments and grow your business. The AI workout builder helps you build, assign and track programs quickly. There is nutrition coaching with custom plans, booking for one-to-one sessions, classes and events, a results tracker to keep clients motivated, habits, metrics and progress photos, and chat. A client-friendly app helps engage and retain clients, and branding tools give you an app under your own name. AI-powered check-ins and a Zapier integration are available as add-ons. There is a 30-day free trial with no card details required.', 'Конструктор тренувань із підтримкою AI
Індивідуальні плани харчування
Бронювання занять і подій
Облік результатів і фото прогресу
