SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'spiideo.com' OR LOWER(`name`) = LOWER('Spiideo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Spiideo', NULL, 'https://spiideo.com', NULL, NULL, 'Автоматизовані рішення для зйомки, трансляції й аналізу спортивних матчів для правовласників, ліг, федерацій, клубів і шкіл: камери без оператора, хмарні повтори для суддів і відеоаналіз Spiideo Perform для тренерів.', 'Automated solutions for capturing, broadcasting and analyzing sports for rights-holders, leagues, federations, clubs and schools: operator-free cameras, cloud replay for officials and Spiideo Perform video analysis for coaches.', 'Spiideo створює автоматизовані відеорішення для спорту: знімати, транслювати й аналізувати кожен момент гри. Ними користуються медіаправовласники, ліги, федерації, клуби та школи по всьому світу. Автоматизація бере на себе повторювану роботу з великим обсягом трансляцій, а команди можуть охоплювати більше змагань і приділяти більше часу редакційній роботі. Хмарна система повторів дозволяє в реальному часі пов''язати кімнату відеоповторів із суддями на полі — такі рішення вже використовують університетські конференції для футболу й баскетболу. Інструмент Spiideo Perform допомагає тренерським штабам керувати постійним циклом підготовки до матчів і розбору ігор, зокрема в хокеї на траві. Для організацій доступна консультація з відділом продажів.', 'Spiideo builds automated sports video solutions to capture, broadcast and analyze every moment of play. They are used by media rights-holders, leagues, federations, clubs and schools around the world. Automation takes on repetitive, high-volume production tasks, so teams can cover more competitions and spend more time on editorial work. A cloud-based replay system links the replay booth to on-field officials in real time, and college conferences already use it for football and basketball. Spiideo Perform helps coaching staffs manage the constant cycle of match preparation and review, for example in field hockey. Organizations can talk to sales for details.', 'Автоматична зйомка й трансляція матчів
Хмарні повтори для суддів у реальному часі
Відеоаналіз Spiideo Perform для тренерів
Рішення для ліг, федерацій і клубів
Віддалена співпраця під час трансляцій', 'Automated match capture and broadcasting
Real-time cloud replay for officials
Spiideo Perform video analysis for coaches
Solutions for leagues, federations and clubs
Remote collaboration during broadcasts', 'Медіаправовласники, ліги, федерації, клуби, університети й школи.', 'Media rights-holders, leagues, federations, clubs, colleges and schools.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
