SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'tacticalpad.com' OR LOWER(`name`) = LOWER('TacticalPad'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TacticalPad', NULL, 'https://tacticalpad.com', NULL, NULL, 'Застосунок для тренерів, щоб малювати вправи, склади й тактичні схеми: планування тренувань, анімації у 2D і 3D, кілька видів спорту й полів, обмін матеріалами з командою. Працює на Windows, Mac, iPad, iPhone і Android.', 'An app for coaches to draw drills, lineups and tactics: session planning, 2D and 3D animations, multiple sports and pitches, and sharing with the team. Runs on Windows, Mac, iPad, iPhone and Android.', 'TacticalPad — застосунок для планування тренувальних сесій і розбору матчів, який допомагає тренерам створювати й поширювати вправи, склади, тактику й цілі заняття. Можна малювати схеми й створювати анімації у 2D та 3D, планувати сесії, працювати з кількома полями й видами спорту, а потім ділитися матеріалами з гравцями й колегами. Підтримуються футбол, футзал, гандбол, баскетбол, хокей на льоду й на траві, регбі, гельські ігри, волейбол, лакрос, теніс, бадмінтон, падел, флорбол та інші види спорту. Застосунок доступний для Windows, macOS, iPad, iPhone і Android та регулярно оновлюється за побажаннями тренерів. Ним користуються клуби, національні збірні, університети й школи. Для команд від чотирьох користувачів є пакетні ліцензії.', 'TacticalPad is a session planning and match analysis app that helps coaches create and share drills, formations, tactics and sessions. You can draw diagrams, create 2D and 3D animations, plan sessions, work with multiple pitches and sports, and then share materials with players and colleagues. It supports football, futsal, handball, basketball, ice and field hockey, rugby, GAA, volleyball, lacrosse, tennis, badminton, padel, floorball and more. The app is available for Windows, macOS, iPad, iPhone and Android and is updated regularly based on coach feedback. It is used by clubs, national teams, universities and schools. Bulk licenses are available for four or more users.', 'Малювання вправ, складів і тактики
Анімації у 2D і 3D
Планування тренувальних сесій
Підтримка багатьох видів спорту й полів
Обмін матеріалами з командою
Робота на комп''ютері, планшеті й телефоні', 'Drawing drills, lineups and tactics
2D and 3D animations
Training session planning
Many sports and pitches
Sharing materials with the team
Works on computer, tablet and phone', 'Тренери футбольних, баскетбольних, хокейних та інших команд, клуби, збірні й навчальні заклади.', 'Coaches of football, basketball, hockey and other teams, clubs, national teams and schools.', 'mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
