-- TeamBuildr — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'teambuildr.com' OR LOWER(`name`) = LOWER('TeamBuildr'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TeamBuildr', NULL, 'https://teambuildr.com', NULL, NULL, 'Програма для тренерів із силової й фізичної підготовки, команд і залів: складання програм, облік максимумів, опитувальники, звіти, вигляд для екранів у тренажерному залі, система керування спортсменами й облік відновлення.', 'Software for strength and conditioning coaches, teams and gyms: program building, max tracking, questionnaires, reports, weight room displays, an athlete management system and recovery monitoring.', 'TeamBuildr — програмне забезпечення для силової й фізичної підготовки, яке використовують шкільні, університетські й професійні команди, а також зали й силові структури. Тренери складають програми з власною бібліотекою вправ, ведуть облік максимумів, збирають дані через опитувальники й отримують звіти. На старших планах є відображення програм на телевізорах і планшетах у залі, база відео вправ, звіти з сирими даними, аналітика тренувань зі швидкістю руху штанги, інтеграції й річний планувальник. Додатковий модуль Strength — система керування спортсменами з моніторингом відновлення, аналізом програм і обліком тренувального обсягу. Окремий продукт для залів містить розклад і бронювання, прийом оплат і кіоск для відміток. Ціни залежать від кількості профілів; є безкоштовний пробний період і демонстрація.', 'TeamBuildr is strength and conditioning software used by high school, college and professional teams as well as gyms and tactical organizations. Coaches build programs with a custom exercise library, track one-rep maxes, collect data through questionnaires and get reports. Higher plans add TV and tablet displays for the weight room, an exercise video database, raw data reports, velocity-based training analytics, integrations and an annual planner. The Strength add-on is an athlete management system with recovery monitoring, program analysis tools and volume load tracking. A separate gym product includes scheduling and booking, payment processing and a check-in kiosk. Pricing depends on the number of profiles; there is a free trial and demos.', 'Складання програм із власною бібліотекою вправ
Облік максимумів і опитувальники
Звіти й сирі дані
Відображення програм на екранах у залі
Аналітика тренувань зі швидкістю руху
Моніторинг відновлення й обсягу навантаження
Розклад, бронювання й оплати для залів', 'Program building with a custom exercise library
Max tracking and questionnaires
Reports and raw data
Weight room screen displays
Velocity-based training analytics
