SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'teamsnap.com' OR LOWER(`name`) = LOWER('TeamSnap'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TeamSnap', NULL, 'https://teamsnap.com', NULL, NULL, 'Платформа для керування дитячими й аматорськими командами, клубами та лігами: реєстрація, оплати, склад, розклад, повідомлення, тренувальні плани й вправи від професійних ліг, а також трансляції з AI-камерою Falcon.', 'A platform for managing youth and amateur teams, clubs and leagues: registration, payments, rosters, schedules, messaging, practice plans and drills from pro leagues, plus livestreaming with the Falcon AI camera.', 'TeamSnap допомагає тренерам, менеджерам команд, батькам, клубам і лігам організувати спортивне життя в одному місці. Для однієї команди застосунок безкоштовний на старті: розклад, спілкування, відмітки про присутність, керування складом, вправи й тренувальні плани, розподіл обов''язків. Тренери можуть перейти на платний план, щоб відстежувати доступність гравців, збільшити розмір складу й отримати вправи від професійних ліг. Для клубів і ліг є платформа TeamSnap ONE: гнучка реєстрація, оплати, формування складів і розкладів, повідомлення на всю організацію, вбудовані безкоштовні трансляції. Нова AI-камера Falcon, створена для TeamSnap ONE, автоматично транслює дитячі матчі. Ціни для клубів і ліг формуються індивідуально.', 'TeamSnap helps coaches, team managers, parents, clubs and leagues organize sports life in one place. For a single team the app is free to start: scheduling, communication, real-time availability, roster management, drills, practice plans and assignments. Coaches can upgrade to unlock availability tracking, larger rosters and skill-building drills from the pros. Clubs and leagues get TeamSnap ONE: flexible registration, payments, roster building and schedules, organization-wide communications, and free built-in live streaming. Falcon, a new AI camera built for TeamSnap ONE, livestreams youth games automatically. Pricing for clubs and leagues is tailored to each organization.', 'Розклад, склад і відмітки про присутність
