SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'teamworks.com' OR LOWER(`name`) = LOWER('Teamworks'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Teamworks', NULL, 'https://teamworks.com', NULL, NULL, 'Єдина платформа для професійних і університетських команд: пошук і відбір талантів, рекрутинг, комунікація, розклади, логістика, силова підготовка, харчування, медична документація й аналітика з підтримкою AI в одному місці.', 'One platform for pro and college teams: data-driven talent acquisition, recruiting, communication, scheduling, logistics, strength and conditioning, nutrition, sports medical records and AI-driven insights in one place.', 'Teamworks — інтегрована технологічна платформа, створена спеціально для елітних спортивних команд, яка оцифровує весь життєвий цикл спортсмена й замінює розрізнені сервіси. Вона поєднує відбір і пошук талантів на основі даних, організацію роботи й комплексний розвиток спортсменів. Комунікація, розклади й обмін файлами тримають гравців і персонал у синхронізації, а автоматизовані процеси, підказки штучного інтелекту й спрощена логістика знімають зайву складність. Продуктова лінійка охоплює операційний центр, відповідність правилам, навчання, керування інвентарем, табори, оцінку гравців і рекрутинг для футболу, бейсболу й хокею, тренерські інструменти, систему керування спортсменами, силову підготовку, харчування й спортивну медичну документацію, а також безкоштовні платежі для спортсменів. Платформою користуються професійні клуби, університети, олімпійські федерації й силові структури.', 'Teamworks is an integrated technology platform built specifically for elite sports teams that digitizes the athlete lifecycle and consolidates the tech stack. It combines data-driven talent acquisition, seamless operations and holistic performance development. Communication, scheduling and file sharing keep athletes and staff in sync, while automated workflows, AI-driven insights and simplified logistics cut through complexity. The product line covers an operations hub, compliance, academics, inventory management, camps, player personnel and recruiting for football, baseball and hockey, coaching tools, an athlete management system, strength and conditioning, nutrition and a sports EMR, plus fee-free payments for athletes. It is used by pro clubs, colleges, Olympic governing bodies and tactical organizations.', 'Комунікація, розклади й обмін файлами
Пошук і відбір талантів, рекрутинг
Тренерські інструменти
Система керування спортсменами й силова підготовка
Харчування й спортивна медична документація
Аналітика й підказки з підтримкою AI
Логістика й операційні процеси', 'Communication, scheduling and file sharing
Talent acquisition and recruiting
Coaching tools
Athlete management and strength & conditioning
Nutrition and sports medical records
AI-driven analytics and insights
Logistics and operations', 'Професійні клуби, університетські спортивні програми, олімпійські федерації й силові структури.', 'Pro clubs, college athletic programs, Olympic governing bodies and tactical organizations.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
