SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'trainheroic.com' OR LOWER(`name`) = LOWER('TrainHeroic'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TrainHeroic', NULL, 'https://trainheroic.com', NULL, NULL, 'Платформа для тренерів із силової підготовки: складання програм, відстеження результатів і спілкування зі спортсменами в одному місці, керування дистанційними й очними клієнтами, а також маркетплейс програм від тренерів.', 'A platform for strength coaches: programming, results tracking and athlete communication in one place, management of remote and in-person clients, plus a marketplace of programs from real coaches.', 'TrainHeroic — професійна платформа для тренерів із силової й фізичної підготовки, яка допомагає перейти від простого надсилання тренувань до повноцінного коучингу. Вона об''єднує інструменти програмування, відстеження результатів і комунікації в єдиному центрі керування, тож не треба вести таблиці. Тренер може вести дистанційних і очних клієнтів в одному місці, забезпечувати якісний досвід спортсменам і збільшувати кількість підопічних без втрати індивідуального підходу. Рутинну адміністративну роботу замінює зручна система, яка тримає клієнтів залученими й відповідальними за результат. Для спортсменів є застосунок і маркетплейс тренувальних програм від реальних тренерів. У блозі — матеріали про побудову силових програм, розминку й залучення спортсменів. Для тренерів є 14-денний безкоштовний період без картки.', 'TrainHeroic is a professional platform for strength and conditioning coaches that helps them move from simply sending workouts to real coaching. It unifies programming, tracking and communication in a single command center, so there are no spreadsheet headaches. Coaches can manage remote and in-person clients in one place, deliver a premium athlete experience and grow their client base without losing the personal touch. A professional system replaces clunky admin work and keeps clients engaged and accountable. Athletes get an app and a marketplace of training programs from real coaches. The blog covers building strength programs, warming up and athlete engagement. Coaches get a 14-day free trial with no credit card required.', 'Складання тренувальних програм
Відстеження результатів спортсменів
Спілкування з клієнтами в одному місці
Ведення дистанційних і очних клієнтів
Маркетплейс програм від тренерів
Застосунок для спортсменів', 'Training program builder
Athlete results tracking
Client communication in one place
Remote and in-person client management
Marketplace of coach-made programs
Athlete app', 'Тренери з силової й фізичної підготовки, які ведуть команди або індивідуальних клієнтів, а також спортсмени.', 'Strength and conditioning coaches working with teams or individual clients, as well as athletes.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
