-- Veo — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'veo.com' OR LOWER(`name`) = LOWER('Veo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Veo', NULL, 'https://veo.com', NULL, NULL, 'AI-камера для спортивних команд: автоматично знімає й транслює матчі, стежачи за грою без оператора, дозволяє розбирати ключові епізоди й ділитися моментами. Підходить для футболу, регбі, хокею на траві, баскетболу та інших видів спорту.', 'An AI camera for sports teams: it records and livestreams matches automatically, following play without a camera operator, and lets you break down key moments and share them. Works for football, rugby, hockey, basketball and more.', 'Veo допомагає тренерам, гравцям і командам будь-якого рівня записувати, аналізувати й транслювати кожен матч — удома й на виїзді. Флагманська камера Veo Cam 3 знімає в 4K, а вбудований штучний інтелект автоматично стежить за грою, тож оператор не потрібен; вона підходить для футболу, регбі, хокею на траві та інших видів спорту на повному полі. Версія Cam 3 5G має вбудований 5G-модем для трансляцій і завантаження записів навіть без Wi-Fi — зручно для виїзних матчів і турнірів. Veo Go перетворює ваш iPhone на розумну камеру для залу, менших полів або щоб спробувати Veo без покупки обладнання. Після матчу можна одразу переглянути гру, розібрати ключові моменти й поділитися найяскравішими епізодами. Плани підписки відрізняються кількістю годин запису, команд і користувачів.', 'Veo helps coaches, players and teams at every level record, analyze and livestream every match, home and away. The flagship Veo Cam 3 records in 4K and its onboard AI follows the action automatically, so no operator is needed; it suits football, rugby, hockey and any full-pitch sport. Cam 3 5G adds a built-in 5G modem for livestreaming and uploading even without Wi-Fi, ideal for traveling clubs and tournaments. Veo Go turns your iPhone into a smart camera for indoor sports, smaller pitches or trying Veo before buying hardware. After the match you can instantly relive the game, break down key plays and share standout moments. Subscription plans differ by recording hours, teams and users.', 'Автоматична зйомка матчів без оператора
Камера Veo Cam 3 з записом у 4K
Версія з 5G для трансляцій без Wi-Fi
Veo Go — камера на базі iPhone
Прямі трансляції матчів
Розбір ключових епізодів після гри
Поширення хайлайтів', 'Automatic match recording without an operator
Veo Cam 3 with 4K capture
5G version for streaming without Wi-Fi
Veo Go camera using an iPhone
Live match streaming
Breakdown of key plays after the game
Highlight sharing', 'Тренери, клуби й команди будь-якого рівня у футболі, регбі, баскетболі, хокеї та інших видах спорту.', 'Coaches, clubs and teams of every level in football, rugby, basketball, hockey and other sports.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
